//! Every nami file option, with an example: `nami options`, the docs and
//! the JSON Schemas.

use super::*;

#[derive(Debug, Serialize)]
pub struct Option_ {
    pub key: &'static str,
    pub kind: &'static str,
    pub summary: &'static str,
    pub example: &'static str,
}

/// Every nami file option, with an example. `nami options` shows these.
pub const OPTIONS: &[Option_] = &[
    Option_ {
        key: "packages",
        kind: "a list: - name, - name: version, or - name: with its own setup under it",
        summary: "What to install, `- name` a line. A package with its own setup is `- name:`, with the setup under it: its files (`~/.gitconfig:` in user.nami, `/etc/...` in system.nami), its desktop settings by schema (`org.gnome.TextEditor:`), `login-shell: true` (zsh, fish), `version:`, and for a Python its packages (`- python3: { version: 3.13, with: [numpy] }`). What's no one package's goes in the file's own `files:`, `settings:`, `env:`...; services are in `services:` (`- syncthing`). Names come from the catalog (`nami search`); a name alone is the newest. `name: version` picks one: `firefox: 150` is the newest 150.x, `python3: 3.12.4` exactly that (`nami versions <name>` lists them). Paths starting with ./ are your own recipes. In your user.nami, `flathub:<app id>` is an app from Flathub (`- flathub:com.spotify.Client`; `nami search <word> --flathub` finds them): installed with Flatpak, for you alone (flatpak --user), and taken off when it comes off the list. On a Mac, `cask:<token>` is an app from Homebrew's casks (`- cask:rectangle`; `nami search` finds them): downloaded from its developer, checked against the cask's sha256 (or, for one without, Apple's notarization), and put in Applications, in nami Apps; a plain name nixpkgs has no ready-built Mac build of is the cask of that name when there is one. Linux leaves casks out. `bundle:github:<owner>/<repo>` (or `bundle:https://<folder>`) is an app made with `nami bundle`, with the key its updates are signed with (`- bundle:github:ada/myapp: { key: 3F2A 9C01 5B7E 22D4 8A10 C3F9 0E6B 7D21 }`; installing one in Settings writes it): downloaded from there and checked against that key, for you alone, and taken off when it comes off the list. A name is the catalog's package, set up by the folder of that name in the nearest packages/ folder above the file when there is one: a program's setup (`tailscale`, `cups`), or a set of packages and settings with no program of its own (`namios`, `namios-look`, `printing`), as an apt metapackage does. A path (`../packages/tailscale`) is used as written; `nixpkgs:niri` is the catalog's package alone, even where a folder has its name. An entry ending in .nami is a set of your own: a file next to this one (`./work.nami`), or one in a git repo (`github:owner/repo/gaming.nami`, `@ref` for a branch or tag; `git+https://host/repo.git@v2#gaming.nami`), pinned in nami.lock the first time (`nami layers --update` moves it). What a set says goes underneath this file: lists joined, settings merged, and where both say something, this file wins. It builds on one set at most; packages only add, and what must be one (timezone, login-screen...) comes down that one line of files. `nami show --flat` prints it all, each line with the file it came from.",
        example: "packages:\n  - namios\n  - ./work.nami\n  - python3: 3.12\n  - openssh:\n      /etc/ssh/sshd_config.d/10-nami.conf: |\n        PasswordAuthentication no\n  - gnome-text-editor:\n      org.gnome.TextEditor:\n        show-line-numbers: true",
    },
    Option_ {
        key: "format",
        kind: "1",
        summary: "The nami file format the file is written in, for any .nami file. Without it, a file is format 1, the only one yet. A later nami that reads files differently will write a higher number, and a nami that doesn't know it says so (`this file needs a newer nami: nami self-update`) instead of reading it wrong.",
        example: "format: 1\npackages:\n  - htop",
    },
    Option_ {
        key: "unfree",
        kind: "true or false",
        summary: "Whether software that isn't free (Steam, Spotify, Discord, ...) may be installed. Allowed unless this is false; such apps are built on your computer, since the binary cache doesn't carry them.",
        example: "unfree: false",
    },
    Option_ {
        key: "replace",
        kind: "map: package -> recipe path or package",
        summary: "Swap a library in every package that uses it, without building them again: a fixed libpng, the day the fix is out. The replacement is a recipe (`extends: libpng` with `patches:`) or another package of the catalog. Each package that uses the library is copied with the old library's path written over by the new one's, as NixOS' replaceDependency does; nami refuses when the new one lacks a soname or a symbol the old had (that needs building again). In one package only: `- firefox: { replace: { libpng: ./libpng-fix } }`. Apply says where it replaced it.",
        example: "replace:\n  libpng: ./recipes/my-tool   # a recipe: extends: libpng, with a patch",
    },
    Option_ {
        key: "updates (system.nami)",
        kind: "auto or manual",
        summary: "Whether the computer installs updates by itself. `auto`, the default: once a day nami gets the newest catalog and the newest nami, then the system's apps (on namiOS, a new version of the system for the next start; the version before stays in the boot menu). `manual`: only when someone clicks Update Now in Updates, or runs `nami os-update` as root. On namiOS `manual` keeps nami-update.timer off, as `without: [nami-update.timer]` does; on another distribution nami adds the timer, or takes it away, when the file is applied.",
        example: "updates: manual",
    },
    Option_ {
        key: "cleanup",
        kind: "a duration (30d), off, or { older-than, keep }",
        summary: "When old changes, and the app versions only they use, are removed by themselves. A change stays after the next one replaces it, so `nami undo` is instant; once it's older than this, it goes, with the files in /nix/store nothing else uses. The current change and the 3 newest always stay, whatever their age. Unset, it's 30 days; `off` keeps old changes until `nami gc`; `{ older-than: 90d, keep: 5 }` says both. In user.nami it's for your own changes, in system.nami for the computer's (on namiOS, the versions in the boot menu: the one running and the one before it always stay). It runs with the daily update, and when you next use nami. When the disk with /nix has less than 10% or 5 GB free, old changes go early, by the same rules but whatever their age. Settings › Storage has the same choice.",
        example: "cleanup: 7d",
    },
    Option_ {
        key: "history",
        kind: "number",
        summary: "How many changes to keep in history, to go back to: after each apply, older ones go (the current one always stays). `keep-generations:` is its old name, which works until nami 1.0.",
        example: "history: 10",
    },
    Option_ {
        key: "caches",
        kind: "list of {url, key}",
        summary: "Extra binary caches to download from before building, such as one you fill with `nami push`.",
        example: "caches:\n  - url: https://cache.example.org\n    key: me-1:6NCHdD59X431o0gWypbMrAURkbJ16ZPMQFGspcDShjY=",
    },
    Option_ {
        key: "env",
        kind: "map of NAME: value",
        summary: "Environment variables: in your user.nami, for your shells and your desktop session; in system.nami or a package.nami, for everyone's logins and desktop, on a computer nami made. A value may use the login's variables: `$HOME`, `$XDG_RUNTIME_DIR`.",
        example: "env:\n  EDITOR: nvim\n  PAGER: less -R\n  SSH_AUTH_SOCK: $XDG_RUNTIME_DIR/gnupg/S.gpg-agent.ssh",
    },
    Option_ {
        key: "aliases (user.nami)",
        kind: "map of name: command",
        summary: "Shell aliases for bash, zsh and fish.",
        example: "aliases:\n  ll: ls -la\n  gs: git status",
    },
    Option_ {
        key: "namios (user.nami)",
        kind: "map",
        summary: "namiOS's desktop, read as the file changes: `dock:` (`on`, `size`: small, medium or large, `magnification`: off, small or large, `position`: bottom, left or right, `hide`, `open-apps`, `pinned`: apps by their menu entry's name), `all-apps: folders:` (All Apps' folders, each a `name` and its `apps` by their menu entry's name), `minimize`: genie or scale, and `backups:` (your home every hour, to go back in time: `on`, true by itself; `to`: `disk:<label>` or a folder, also there; `leave-out`: folders, or names and patterns anywhere, in place of the usual caches and the Trash; `nami backup status` says what it does).",
        example: "namios:\n  dock:\n    on: true\n    size: medium\n    position: bottom\n    pinned: [firefox, org.gnome.Nautilus]\n  minimize: genie",
    },
    Option_ {
        key: "shell (user.nami)",
        kind: "map of bash|zsh|fish: lines",
        summary: "Lines run at the end of your shell's startup, in interactive shells: prompts, plugins, tools' init lines. `nami_share <path>` finds an installed package's share/<path>.",
        example: "shell:\n  zsh: |\n    eval \"$(starship init zsh)\"\n    source \"$(nami_share zsh-autosuggestions/zsh-autosuggestions.zsh)\"",
    },
    Option_ {
        key: "login-shell (user.nami)",
        kind: "zsh | fish",
        summary: "The shell your terminals open: their bash hands over to it, without root or chsh. A bash you start from it stays bash, and while it isn't installed nothing changes.",
        example: "packages:\n  - zsh:\n      login-shell: true",
    },
    Option_ {
        key: "with (packages: python3)",
        kind: "a list of package names",
        summary: "A Python with its packages, as nixpkgs' python3.withPackages makes one: `python3 -c 'import numpy'` works, `pip list` lists them, and their programs (django-admin) are on PATH. Under a Python in packages: (python3, python313), with `version:` for its line (3.13). The packages are that Python's own set in the catalog (python313Packages), with the Python packages each needs, so every one is made for that very interpreter. pip comes with it. In any nami file: your apps, the computer's, or a project's tools.",
        example: "packages:\n  - python3:\n      version: 3.13\n      with: [numpy, requests, django]",
    },
    Option_ {
        key: "files (user.nami: settings)",
        kind: "path: nested settings",
        summary: "A file in your home (in user.nami every file is ~/...), as settings written in its own format, picked from the file name: .json, .toml, .yaml, .ini/.conf, gitconfig, .env.",
        example: "packages:\n  - git:\n      ~/.gitconfig:\n        user: { name: Ada, email: ada@example.org }\n        init: { defaultBranch: main }",
    },
    Option_ {
        key: "files (user.nami: text)",
        kind: "path: text",
        summary: "A file with exactly this text, for a format nami doesn't write itself (a vimrc, a script, Lua, KDL...). JSON, TOML, YAML, INI and gitconfig files are always settings (nested YAML), never text; to keep one as it is, put it in your repo and use `{ source: ./... }`.",
        example: "files:\n  ~/.vimrc: |\n    set number\n    syntax on",
    },
    Option_ {
        key: "files (user.nami: source)",
        kind: "path: { source: ./path }",
        summary: "A file or folder copied from next to your nami file.",
        example: "files:\n  ~/.config/nvim: { source: ./dotfiles/nvim }",
    },
    Option_ {
        key: "settings",
        kind: "schema: { key: value }",
        summary: "Desktop settings (GNOME and other GSettings apps), applied with gsettings. Keys you remove are reset to their defaults; rollback restores earlier values. In system.nami they're what everyone starts with (each person can still change theirs); in user.nami, yours. A value YAML can't say (a tuple, a dictionary) is GVariant text tagged `!gvariant`; a relocatable schema takes its path, `schema:/path/`.",
        example: "settings:\n  org.gnome.desktop.interface:\n    color-scheme: prefer-dark\n    clock-format: 24h\n  org.gnome.desktop.wm.preferences:\n    num-workspaces: 4\n  org.gnome.desktop.input-sources:   # GVariant text, for what YAML can't say\n    sources: !gvariant \"[('xkb', 'us'), ('xkb', 'dk')]\"",
    },
    Option_ {
        key: "env (user.nami: secret)",
        kind: "NAME: !secret ...",
        summary: "An environment variable whose value is a secret, encrypted right in the file (write it plain, `!secret hunter2`, and `nami secret seal` encrypts it; see `nami secret`). It's decrypted into private files of yours on apply, never into the store.",
        example: concat!("env:\n  GITHUB_TOKEN: !secret \"", sealed_example!(), "\""),
    },
    Option_ {
        key: "files (user.nami: secret)",
        kind: "path: !secret ..., or settings with secrets in them, or { content, mode }",
        summary: "A file with a secret in it (the whole file, or a setting in it), written for you alone (mode 0600, or the mode you give), never into the store.",
        example: concat!("files:\n  ~/.config/rclone/rclone.conf:\n    s3: { type: s3, secret_access_key: !secret \"", sealed_example!(), "\" }\n  ~/.ssh/id_ed25519: { content: !secret \"", sealed_example!(), "\", mode: \"0600\" }"),
    },
    Option_ {
        key: "files (user.nami: mutable)",
        kind: "path: { mutable: true, content|source }",
        summary: "A normal, editable copy instead of a read-only link, for apps that save their own settings. Your edits are kept unless nami file changes the file.",
        example: "files:\n  ~/.config/Code/User/settings.json:\n    mutable: true\n    content: { editor.fontSize: 14 }",
    },
    Option_ {
        key: "files (user.nami: options)",
        kind: "path: { content|source, mode, owner, group, mutable, reload, restarts }",
        summary: "A file's options, the same in every nami file, for a file in a home and one in /etc. They're options only with `content:` (what it says: text or settings) or `source:` (a file or folder next to the nami file), so a settings file can still have a `mode:` key of its own. `mode:` is its permissions (\"0640\"); a file in your home with a mode is written in place, as one with a secret is. `owner:` and `group:` are for the computer's files (in /etc or /run, with a secret in them). `mutable: true` is for a file in a home that apps may change. `reload:` and `restarts:` are for the computer's files, when nami changes one (see files (reload, restarts)). A key a file can't have where it is is refused, saying where it goes.",
        example: "files:\n  ~/.netrc:\n    content: \"machine example.org login ada password hunter2\\n\"\n    mode: \"0400\"\n  ~/.config/app/config.yaml:\n    content: { theme: dark }\n    mode: \"0600\"",
    },
    Option_ {
        key: "services (package)",
        kind: "- name, or - unit.type",
        summary: "Run the systemd unit a package ships (lib/systemd/system/<name>.service; a template's instance as name@instance), enabled and started. The package is installed with it. In system.nami it's the computer's; in your user.nami it's yours (systemctl --user). Named whole (`cups.socket`, `pipewire-pulse.socket`), it's that unit, from whichever installed package brings it; in system.nami, `{ per-person: true }` turns it on for each person, as they log in. Needs systemd.",
        example: "services:\n  - syncthing@ada\n  - cups.socket",
    },
    Option_ {
        key: "services (package, changed)",
        kind: "- name: { enable, package, env, after, restart, user }",
        summary: "A package's unit with changes (written as a drop-in). `package:` when the unit isn't named after its package; `enable: false` installs it without starting it.",
        example: "services:\n  - tailscaled:\n      package: tailscale\n      env: { PORT: \"41641\" }\n      restart: always",
    },
    Option_ {
        key: "services (your own)",
        kind: "name: { run, script, at, user, env, after, restart, dir, description, systemd }",
        summary: "Your own service. `run:` is the command line; a command's name is looked up in your packages, then the system profile, then /usr/bin and the like. System services run as a fresh user with /var/lib/<name> for data unless `user:` names one. Restarts on failure unless `restart:` says otherwise. Changing it restarts it; removing it stops it.",
        example: "services:\n  - myapp:\n      run: myapp-server --port 8080\n      env: { RUST_LOG: info }\n      after: [network-online.target]\n      user: myapp",
    },
    Option_ {
        key: "services (script, timer)",
        kind: "name: { script, at }",
        summary: "A service whose command is several lines: `script:` runs them with bash -e (instead of `run:`). `at:` starts it on a schedule (systemd's OnCalendar: daily, weekly, *-*-* 04:00) through a timer, instead of at boot; it isn't restarted after it finishes.",
        example: "services:\n  - backup:\n      script: |\n        cd /srv\n        tar czf /backup/srv.tgz .\n      at: daily",
    },
    Option_ {
        key: "services (systemd keys)",
        kind: "name: { systemd: { Unit|Service|Install|Timer: { Key: value } } }",
        summary: "Any other systemd setting, written into the unit (or a package unit's drop-in) as it is; a list for a key that repeats. Your own User= or Restart= replaces nami's default; Install's WantedBy replaces the default target.",
        example: "services:\n  - backup:\n      script: restic backup /home\n      systemd:\n        Service: { Type: oneshot, Nice: 10, IOSchedulingClass: idle }\n        Unit: { Before: [sleep.target] }",
    },
    Option_ {
        key: "services (its files)",
        kind: "name: { /etc/path: text, settings or { source } }",
        summary: "A service's own files go under it, written as files: are (text, settings in the file's own format, or a file from your repo); the service restarts when nami changes one. An app's setup goes under what turns it on: a service's here, a program's under its package. An entry with only files is on.",
        example: "services:\n  - adguardhome:\n      /etc/adguardhome.yaml:\n        dns: { port: 53 }\n  - myapp:\n      run: myapp-server --config /etc/myapp/config.toml\n      /etc/myapp/config.toml:\n        port: 8080",
    },
    Option_ {
        key: "files",
        kind: "/etc/path: text, settings or { source }",
        summary: "In system.nami: files under /etc, written as a person's are: text as is, settings in the file's own format, or a file or folder from next to the nami file. A file already there is kept as <file>.nami-backup and comes back when you remove the entry. /etc/passwd, shadow, sudoers, fstab and the like are refused.",
        example: "files:\n  /etc/ssh/sshd_config.d/10-nami.conf: |\n    PasswordAuthentication no\n  /etc/myapp/config.toml:\n    port: 8080",
    },
    Option_ {
        key: "files (mode)",
        kind: "/etc/path: { content|source, mode }",
        summary: "A file with its own permissions (default 0644), owned by root.",
        example: "files:\n  /etc/sudoers.d/90-ops:\n    content: \"%ops ALL=(ALL) ALL\\n\"\n    mode: \"0440\"",
    },
    Option_ {
        key: "files (secret)",
        kind: "/etc/path or /run/path: { content, owner, group, mode }, with a !secret in it",
        summary: "On a computer nami made: a file with a secret in it (the whole file, or a setting in it). It's decrypted with the computer's own key as the computer starts, into /run (memory, never the disk or the store): root's alone (0600; 0400 in /run/nami/secrets), or `owner:`/`group:`/`mode:`'s. An /etc path links to it. A file under /run without a secret is written as the computer starts too (0644 unless `mode:` says). Wi-Fi networks: `wifi:`.",
        example: concat!("files:\n  /run/nami/secrets/backup-token:\n    content: !secret \"", sealed_example!(), "\"\n    owner: backup\n    mode: \"0400\""),
    },
    Option_ {
        key: "files (reload, restarts)",
        kind: "/etc/path or /run/path: { content|source, reload, restarts }",
        summary: "What to run when nami changes the file on a running computer (`nami apply`), so what reads it sees the change: `reload:` a command (or a list), `restarts:` a unit (or a list), restarted if it's running (`restart:` before, which still works until nami 1.0; a service's own `restart:` is when systemd starts it again). Not as the computer starts: everything starts with the new files then. When a package's file gives a file with these and yours gives just its text or settings, yours is its `content:`: the two contents merge (settings key by key, text replaced) and the options stay; that's how `packages: [tailscale]` and your /etc/tailscale/up.conf go together.",
        example: "files:\n  /etc/ssh/sshd_config.d/10-nami.conf:\n    content: \"PasswordAuthentication no\\n\"\n    restarts: sshd.service\n  /etc/NetworkManager/conf.d/90-dns.conf:\n    content: { main: { dns: default } }\n    reload: nmcli general reload",
    },
    Option_ {
        key: "wifi",
        kind: "name: { password, ssid, security, hidden, autoconnect, identity, eap, phase2 }",
        summary: "On a computer nami made: Wi-Fi networks, by name. With a password (a `!secret`) it's WPA2 or WPA3, without one it's open; a company's is `security: enterprise` with `identity:` and `password:` (`eap:` peap or ttls, `phase2:` mschapv2 or pap); `security: sae` is WPA3 only. Each is a NetworkManager connection in /run/NetworkManager/system-connections (root's alone), its password opened with the computer's key as it starts; `nami apply` tells NetworkManager at once. `ssid:` when the network's name isn't the entry's, `hidden: true`, `autoconnect: false`.",
        example: concat!("hostname: laptop\nwifi:\n  home: { password: !secret \"", sealed_example!(), "\" }\n  cafe: {}\n  office: { security: enterprise, identity: ada, password: !secret \"", sealed_example!(), "\" }"),
    },
    Option_ {
        key: "tailscale",
        kind: "- ../packages/tailscale, and files: /etc/tailscale/up.conf { set, up }",
        summary: "On a computer nami made: Tailscale, nami's tailscale example (`nami new laptop --from tailscale` copies it to ../packages). Without settings, `sudo tailscale up` logs in in the browser. Its settings are a file, /etc/tailscale/up.conf: `set:` holds `tailscale set` flags (hostname, operator, ssh, accept-routes, exit-node, advertise-exit-node, advertise-routes, ...), applied at every start and when `nami apply` changes them, without logging in again; `up:` the flags only `tailscale up` takes (login-server, advertise-tags). An auth key in /run/nami/secrets/tailscale-auth-key (a `!secret`) logs it in by itself the first time it starts. An exit node or subnet router also lists tailscale-router (IP forwarding). MagicDNS names resolve through systemd-resolved, as on Ubuntu.",
        example: concat!("packages:\n  - ../packages/tailscale\nhostname: laptop\nfiles:\n  /etc/tailscale/up.conf:\n    set: { operator: ada, ssh: true, accept-routes: true }\n  /run/nami/secrets/tailscale-auth-key: !secret \"", sealed_example!(), "\""),
    },
    Option_ {
        key: "env (project secret)",
        kind: "NAME: !secret ...",
        summary: "In a project's project.nami: an environment variable that's a secret, encrypted right in the file. `nami shell`, `run`, `env` and `up` decrypt it with your key, into their environment only. A service's env: and exports: take them too.",
        example: concat!("env:\n  STRIPE_KEY: !secret \"", sealed_example!(), "\""),
    },
    Option_ {
        key: "packages (project: sets)",
        kind: "an entry ending in .nami: a path, or a file in a git repo",
        summary: "In a project's project.nami: the set it builds on (one; that set can list another), shared by a team: a file in the repo (`./nami/common.nami`), or one in a git repo (`github:owner/repo/node.nami[@ref]`, `git+https://host/repo.git@ref#node.nami`). Their packages, env, tasks and services are the project's too; lists are joined, settings merged, and where both say something, the project's own file wins. A set from a repo is pinned to a commit in the project's nami.lock the first time (nami says which), so whoever clones the project gets the same; `nami layers --update` (or `nami shell --upgrade`) moves it, and `--locked` refuses one that isn't pinned. In a repo's set, ./paths and names are its repo's; tasks and services run in the project's folder. A set from a repo can't bring secrets: they go in the project's own file. `nami hook` uses only what's pinned and fetched.",
        example: "packages:\n  - github:acme/dev/node-service.nami\n  - nodejs: 22",
    },
    Option_ {
        key: "services (project, files)",
        kind: "- ./services/<name>.nami, or with { version, port, ports, args, env, exports, ... } under it",
        summary: "In a project's project.nami: what it needs running while you work on it, started by `nami up` (`-d`: in the background) and stopped by `nami down`; no root or systemd. A service file is listed by its path and named after it (./services/postgres.nami is postgres); nami's examples/services has postgres, mysql (MariaDB), redis and mailpit to copy into your project. Their data, sockets and logs are in the project's .nami folder. What they give the project (DATABASE_URL, PGHOST, REDIS_URL, SMTP_PORT, ...) is in `nami shell`, `nami run` and `nami env`. `version:` picks their package's version; any other key changes theirs.",
        example: "services:\n  - ./services/postgres.nami\n  - ./services/redis.nami: { version: 7 }\n  - ./services/mailpit.nami: { port: 2525 }",
    },
    Option_ {
        key: "services (project, your own)",
        kind: "name: { run, env, dir, port, ports, ready, ready-timeout, restart, as-root, init, exports, stop-signal, packages }",
        summary: "A project's own process, run like a service file's: `run:` with the project's tools and environment, in the project's folder (or `dir:`). `ready:` is a command that succeeds once it's ready (else its ports answering is), within `ready-timeout:` (3 minutes; `10m`, `600`); it's restarted when it ends, after 1s, 2s, 4s, ... up to 30s (`restart: on-failure` only when it fails, `restart: no` never); `as-root: no`: it won't run as root, so as root nami runs it as nobody; `init:` runs once, before its first start; `exports:` are variables it gives the project. {state} (its folder in .nami), {sockets} (a short folder for its unix sockets), {port}, {port.<name>}, {project} and {project.dir} are filled in. A second postgres is a copy of its service file by another name (./services/testdb.nami).",
        example: "services:\n  - worker:\n      run: npm run worker\n      env: { QUEUE: default }\n  - ./services/testdb.nami: { port: 5433 }",
    },
    Option_ {
        key: "desktop",
        kind: "niri, or a list",
        summary: "A namiOS computer, made with `nami usb` (system.nami): the desktops to pick from on its login screen. The first is the default. Each comes with its package folder in packages: (niri's, which namios lists); `desktop:` picks and orders them. None: a computer with a text console, like a server.",
        example: "packages:\n  - ../packages/namios\ndesktop: niri\nhostname: laptop",
    },
    Option_ {
        key: "login-screen",
        kind: "gdm or greetd",
        summary: "The login screen (the display manager), when the desktops' files bring more than one: namiOS's own is on greetd, niri's alone GDM. Left out, it's the one listed nearest this file (namios's own, before niri's GDM); listed as near, the file must say (nami check asks). Each is its package's folder (gdm's, namios-greeter's, in nami's examples), and the name is its service's.",
        example: "packages:\n  - ../packages/niri\n  - ../packages/namios-greeter\nlogin-screen: greetd",
    },
    Option_ {
        key: "users",
        kind: "name: { admin, name, password, groups, child, hours, without }",
        summary: "Who can log in. Made from a config repo (`nami usb github:you/nami-config`, or a clone of it), the first admin gets the repo's user.nami at their first login, as `nami apply <repo>` gives it; anyone else runs that with their own repo. Without `password` (a hash from `mkpasswd`), `nami usb` asks for one. `groups` are more groups they're in, as `usermod -aG` would put them (`docker`: docker without sudo). With no users, `nami usb` asks for one (an admin). `child: true` is a child (parental controls, the parental-controls package that desktop lists): no sudo, and no apps of their own (the computer's are theirs, an admin chooses them); `hours` is when they may use the computer (they log in only then, and their session ends when the hours do), `without` the apps they can't use (off their menu).",
        example: "users:\n  ada:\n    admin: true\n    name: Ada\n    groups: [docker]\n  sam:\n    child: true\n    hours: 07:00-20:00\n    without: [discord, steam]",
    },
    Option_ {
        key: "hostname / timezone / language / keyboard",
        kind: "text",
        summary: "The computer's name, time zone, language (a locale) and keyboard layout. Left out, the name is `nami`, and the rest are those of the computer `nami usb` runs on (else UTC, en_US.UTF-8 and us).",
        example: "hostname: laptop\ntimezone: Europe/Copenhagen\nlanguage: da_DK.UTF-8\nkeyboard: dk",
    },
    Option_ {
        key: "services (a package's unit, by its whole name)",
        kind: "unit.type, or unit.type: { per-person: true }",
        summary: "How a package runs on the computer, in its package.nami (used whenever the computer has that package). A service named whole (`cups.socket`, `docker.service`) is a unit the packages bring, turned on where its [Install] says (as `systemctl enable`); `{ per-person: true }`: each person's own, as they log in.",
        example: "services:\n  - cups.socket\n  - pipewire.socket: { per-person: true }\nfiles:\n  /etc/tmpfiles.d/cups.conf: |\n    d /var/spool/cups 0710 root lp -",
    },
    Option_ {
        key: "files (package.nami: a systemd unit)",
        kind: "/etc/systemd/system/<name>: text",
        summary: "A service a package needs and doesn't bring (nixpkgs leaves some to NixOS), where systemd looks for it: /etc/systemd/system/<name>, each person's at /etc/systemd/user/<name> (started as they log in), or a change to one as a drop-in (/etc/systemd/system/gdm.service.d/nami.conf). Turn it on in services:.",
        example: "services:\n  - avahi-daemon.service\nfiles:\n  /etc/systemd/system/avahi-daemon.service: |\n    [Unit]\n    Description=Avahi mDNS/DNS-SD Stack\n    [Service]\n    ExecStart=/run/current-system/sw/bin/avahi-daemon --syslog\n    [Install]\n    WantedBy=multi-user.target",
    },
    Option_ {
        key: "files (package.nami: made by a script)",
        kind: "path: { script, tools }",
        summary: "A file or folder worked out from what's installed, as the system is put together: a shell script writes it to $out ($packages: every package's folder; coreutils, grep, sed and find to hand). `tools` are packages whose programs it runs, fetched for that and not put on the computer.",
        example: "files:\n  /etc/nami-os/schemas:\n    tools: [glib.dev]\n    script: |\n      mkdir -p \"$out\"\n      for p in $packages; do cp \"$p\"/share/glib-2.0/schemas/*.xml \"$out\"/ 2>/dev/null || true; done\n      glib-compile-schemas \"$out\"",
    },
    Option_ {
        key: "login (package.nami)",
        kind: "program: login | password | su | rules; all: lines",
        summary: "The login rules (PAM). A program a package brings that checks who you are gets its rules: `login` (as logging in), `password` (the password alone), `su` (root goes ahead, anyone else gives their password), or the rules themselves. `all:` are lines for every way to log in, each after nami's own of its kind; an `auth sufficient` one (a fingerprint) is tried before the password.",
        example: "login:\n  sudo: su\n  all:\n    - auth sufficient /run/current-system/sw/lib/security/pam_fprintd.so max-tries=1 timeout=10",
    },
    Option_ {
        key: "setuid (package.nami)",
        kind: "list of paths in the packages",
        summary: "Programs that act as root for whoever runs them (sudo, passwd, mount), copied to /run/wrappers/bin with the setuid bit, as they must be.",
        example: "setuid: [bin/sudo]",
    },
    Option_ {
        key: "groups (package.nami)",
        kind: "group: everyone | admins",
        summary: "Groups the people on the computer join, everyone or its admins (the group itself comes from the package's sysusers file).",
        example: "groups:\n  scanner: everyone\n  lpadmin: admins",
    },
    Option_ {
        key: "name-lookup (package.nami)",
        kind: "list of NSS entries",
        summary: "Ways to look up computers' names before DNS, in /etc/nsswitch.conf's hosts line; their modules are found in the packages.",
        example: "name-lookup: [\"mdns_minimal [NOTFOUND=return]\"]",
    },
    Option_ {
        key: "boot (package.nami)",
        kind: "kernel, microcode, initrd-programs, initrd-modules, kernel-options",
        summary: "What starts before the computer's own disk is there: `kernel` (by its nixpkgs name: `linux_zen`, `linux_xanmod`; nixpkgs' default without; the packages built for a kernel, `linuxPackages.nvidia_x11`, are then that one's: kernel-zen lists it), `microcode` (archives the kernel reads first, from the packages: the processor's updates), `initrd-programs` and `initrd-modules` (what the initrd needs: cryptsetup and dm_crypt, to unlock an encrypted disk), `kernel-options` (the kernel's command line, in every boot entry: a hardware fix like `pcie_aspm=off`; each package's are joined).",
        example: "boot:\n  initrd-programs: [bin/cryptsetup]\n  initrd-modules: [dm_crypt, xts]\n  kernel-options: [pcie_aspm=off]",
    },
    Option_ {
        key: "drivers (package.nami)",
        kind: "firmware, graphics, graphics-32bit, kernel-modules: lists of package names",
        summary: "Drivers: `firmware` goes in /lib/firmware (`linux-firmware`, in base); `graphics` are the graphics drivers, whose libraries go together in /run/opengl-driver, where OpenGL, EGL, Vulkan and GBM look (`mesa`, in desktop); `graphics-32bit` are their 32-bit builds, in /run/opengl-driver-32, for 32-bit programs (`pkgsi686Linux.mesa`, in steam); `kernel-modules` are packages of modules built for the system's kernel (linuxPackages), which join its own in /lib/modules. packages/nvidia/package.nami has all three.",
        example: "drivers:\n  firmware: [linuxPackages.nvidia_x11.firmware]\n  graphics: [linuxPackages.nvidia_x11.out]\n  kernel-modules: [linuxPackages.nvidia_x11_stable_open]",
    },
    Option_ {
        key: "libraries (package.nami)",
        kind: "list of package names",
        summary: "Libraries for programs built for other distributions (a downloaded tarball, an AppImage, a game, npm's and pip's prebuilt programs): they ask for their loader at /lib64/ld-linux-x86-64.so.2, which is nix-ld when a package lists it, and it finds their libraries in these packages' lib/ (a package's lib output too), and only for them: the system's own programs don't see them. Each package's are joined; other-linuxes and other-linuxes-desktop list a generous set. A person's own come with `nami libraries --add <program>`.",
        example: "packages: [nix-ld]\nlibraries: [zlib, openssl, libx11, gtk3]",
    },
    Option_ {
        key: "checks.nami (next to a package.nami)",
        kind: "name: { run, expect }",
        summary: "How to tell a package works, on a computer nami made: a name, a command, and what its output has (a regular expression). It's a file of its own next to the package.nami; tests/usb.sh runs them all.",
        example: "\"printing runs\":\n  run: lpstat -r\n  expect: \"scheduler is running\"",
    },
    Option_ {
        key: "without",
        kind: "list of package or service names",
        summary: "Packages the packages you list bring that you don't want on the computer. A package folder's name (`printing`, `plymouth`) leaves out that folder wherever it's listed, with all it sets up. A service named whole (`systemd-networkd.service`) is kept off on a computer nami made (masked): the computer's, or each person's (`gcr-ssh-agent.socket`).",
        example: "packages:\n  - ../packages/namios\nwithout:\n  - printing\n  - gnome-calculator",
    },
    Option_ {
        key: "secure-boot (package.nami)",
        kind: "shim / mokmanager: { from, sha256, file }",
        summary: "Where the computer's Secure Boot start comes from: shim (signed by Microsoft) and its MokManager, a file each in a Debian package (`from`: its addresses, the first that answers; its `sha256`; the `file` in it). nami's own is packages/secure-boot/package.nami, which base lists; shim starts systemd-boot and kernels signed with the computer's own key.",
        example: "secure-boot:\n  shim:\n    from: https://deb.debian.org/debian/pool/main/s/shim-signed/shim-signed_1.51+16.1-2_amd64.deb\n    sha256: ...\n    file: usr/lib/shim/shimx64.efi.signed\n  mokmanager:\n    from: https://deb.debian.org/debian/pool/main/s/shim-helpers-amd64-signed/shim-helpers-amd64-signed_1+16.1+2_amd64.deb\n    sha256: ...\n    file: usr/lib/shim/mmx64.efi.signed",
    },
    Option_ {
        key: "hardware (package.nami)",
        kind: "pci / usb: a list of \"vendor:device\" (hex), or \"vendor:*\" for any of the vendor's",
        summary: "What hardware the package is for, by the ids `lspci -nn` and `lsusb` show. `nami doctor` says which packages (nami's examples and your packages/ folder's) a computer's devices are for and how to add one it doesn't list; `nami check` of the computer's own file notes a listed one it has nothing for (fine when the file is for other computers too). It changes nothing that's installed: nvidia's drivers load only with an NVIDIA card either way.",
        example: "hardware:\n  pci: [\"10de:1b80\", \"10de:1b81\"]\n  usb: [\"046d:*\"]",
    },
    Option_ {
        key: "source (package.nami: a recipe)",
        kind: "{ url } | { url, sha256 } | { path } | one for each kind of computer: { x86_64-linux: { url, sha256 }, aarch64-linux: { url, sha256 } }",
        summary: "What a recipe builds from: a tarball or zip at a URL, or a folder (`path`, from the recipe's). A URL's sha256 needn't be written: the first build records it in the nami.lock next to package.nami, and after that a file that isn't the same is refused, with what changed (`nami recipe update --refetch` takes the new one). `nami recipe from-url` and `nami recipe new` write the recipe for you. A program that comes ready-made has a download for each kind of computer: put each under its kind (`x86_64-linux`, `aarch64-linux`), and each computer builds from its own.",
        example: "source:\n  url: https://github.com/BurntSushi/ripgrep/archive/refs/tags/14.1.1.tar.gz",
    },
    Option_ {
        key: "build-system (package.nami: a recipe)",
        kind: "cargo | go | python | node | meson | cmake | autotools | make",
        summary: "How a recipe is built, when its source's files shouldn't decide. Without it nami works it out: Cargo.toml is cargo (its crates as Cargo.lock pins them), go.mod go (its modules as go.sum pins them), meson.build meson, CMakeLists.txt cmake, configure (or configure.ac) autotools, pyproject.toml or setup.py python (deps are the catalog's Python packages), package.json node (npm, its packages as package-lock.json pins them), a Makefile make. Dependencies are fetched before the build, which never has the network. A recipe with build steps of its own (`build:`, `install:`) is built as they say. `cargo-flags` and `go-flags` are added to `cargo build` and `go install`.",
        example: "source:\n  url: https://github.com/BurntSushi/ripgrep/archive/refs/tags/14.1.1.tar.gz\nbuild-system: cargo\ncargo-flags: [--features, pcre2]",
    },
];
